  6468  static int
  6469  md_process_line(MD_CTX* ctx, const MD_LINE_ANALYSIS** p_pivot_line, MD_LINE_ANALYSIS* line)
  6470  {
  6471      const MD_LINE_ANALYSIS* pivot_line = *p_pivot_line;
  6472      int ret = 0;
  6473
  6474      /* Blank line ends current leaf block. */
  6475      if(line->type == MD_LINE_BLANK) {
  6476          MD_CHECK(md_end_current_block(ctx));
  6477          *p_pivot_line = &md_dummy_blank_line;
  6478          return 0;
  6479      }
  6480
  6481      if(line->enforce_new_block)
  6482          MD_CHECK(md_end_current_block(ctx));
  6483
  6484      /* Some line types form block on their own. */
  6485      if(line->type == MD_LINE_HR || line->type == MD_LINE_ATXHEADER) {
  6486          MD_CHECK(md_end_current_block(ctx));
  6487
  6488          /* Add our single-line block. */
  6489          MD_CHECK(md_start_new_block(ctx, line));
  6490          MD_CHECK(md_add_line_into_current_block(ctx, line));
  6491          MD_CHECK(md_end_current_block(ctx));
  6492          *p_pivot_line = &md_dummy_blank_line;
  6493          return 0;
  6494      }
  6495
  6496      /* MD_LINE_SETEXTUNDERLINE changes meaning of the current block and ends it. */
  6497      if(line->type == MD_LINE_SETEXTUNDERLINE) {
  6498          MD_ASSERT(ctx->current_block != NULL);
  6499          ctx->current_block->type = MD_BLOCK_H;
  6500          ctx->current_block->data = line->data;
  6501          ctx->current_block->flags |= MD_BLOCK_SETEXT_HEADER;
  6502          MD_CHECK(md_add_line_into_current_block(ctx, line));
  6503          MD_CHECK(md_end_current_block(ctx));
  6504          if(ctx->current_block == NULL) {
  6505              *p_pivot_line = &md_dummy_blank_line;
  6506          } else {
  6507              /* This happens if we have consumed all the body as link ref. defs.
  6508               * and downgraded the underline into start of a new paragraph block. */
  6509              line->type = MD_LINE_TEXT;
  6510              *p_pivot_line = line;
  6511          }
  6512          return 0;
  6513      }
  6514
  6515      /* MD_LINE_TABLEUNDERLINE changes meaning of the current block. */
  6516      if(line->type == MD_LINE_TABLEUNDERLINE) {
  6517          MD_ASSERT(ctx->current_block != NULL);
  6518          MD_ASSERT(ctx->current_block->n_lines == 1);
  6519          ctx->current_block->type = MD_BLOCK_TABLE;
  6520          ctx->current_block->data = line->data;
  6521          MD_ASSERT(pivot_line != &md_dummy_blank_line);
  6522          ((MD_LINE_ANALYSIS*)pivot_line)->type = MD_LINE_TABLE;
  6523          MD_CHECK(md_add_line_into_current_block(ctx, line));
  6524          return 0;
  6525      }
