  6527      /* Admonition's leading line needs special treatment. */
  6528      if((ctx->parser.flags & MD_FLAG_ADMONITIONS)  &&
  6529         ctx->n_containers > 0  &&  ctx->containers[ctx->n_containers-1].ch == _T('>')  &&
  6530         ctx->current_block == NULL  &&  ctx->n_block_bytes >= (int)sizeof(MD_BLOCK))
  6531      {
  6532          MD_BLOCK* block = (MD_BLOCK*)((char*)ctx->block_bytes + ctx->n_block_bytes - sizeof(MD_BLOCK));
  6533
  6534          if(block->type == MD_BLOCK_QUOTE  &&  line->end - line->beg > 3  &&  line->end - line->beg < 16  &&
