  6536          {
  6537              unsigned i;
  6538
  6539              for(i = 0; i < SIZEOF_ARRAY(MD_ADMONITION_TAGS); i++) {
  6540                  if(md_ascii_case_eq(STR(line->beg+2), MD_ADMONITION_TAGS[i], md_strlen(MD_ADMONITION_TAGS[i]))) {
  6541                      ctx->containers[ctx->n_containers-1].is_admonition = TRUE;
  6542                      block->type = MD_BLOCK_ADMONITION;
  6543                      block->data = i;
  6544                      return 0;
  6545                  }
  6546              }
  6547          }
  6548      }
  6549
  6550      /* The current block also ends if the line has different type. */
  6551      if(line->type != pivot_line->type)
  6552          MD_CHECK(md_end_current_block(ctx));
  6553
  6554      /* The current line may start a new block. */
  6555      if(ctx->current_block == NULL) {
  6556          MD_CHECK(md_start_new_block(ctx, line));
  6557          *p_pivot_line = line;
  6558      }
