  5070      while(byte_off < ctx->n_block_bytes) {
  5071          MD_BLOCK* block = (MD_BLOCK*)((char*)ctx->block_bytes + byte_off);
  5072          union {
  5073              MD_BLOCK_UL_DETAIL ul;
  5074              MD_BLOCK_OL_DETAIL ol;
  5075              MD_BLOCK_LI_DETAIL li;
  5076              MD_BLOCK_ADMONITION_DETAIL adm;
