  5086                  det.ol.start = block->n_lines;
  5087                  det.ol.is_tight = (block->flags & MD_BLOCK_LOOSE_LIST) ? FALSE : TRUE;
  5088                  det.ol.mark_delimiter = (CHAR) block->data;
  5089                  break;
  5090
  5091              case MD_BLOCK_LI:
  5092                  det.li.is_task = (block->data != 0);
  5093                  det.li.task_mark = (CHAR) block->data;
  5094                  det.li.task_mark_offset = (OFF) block->n_lines;
